package br.com.rj3dart.expedicao;

import android.app.*;
import android.os.*;
import android.content.*;
import android.graphics.*;
import android.graphics.drawable.*;
import android.net.Uri;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import org.json.*;
import java.io.*;
import java.net.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.text.Normalizer;
import java.util.*;
import java.util.concurrent.*;

public class MainActivity extends Activity {
    private final int NAVY=Color.rgb(20,30,44), MUTED=Color.rgb(108,119,133), BG=Color.rgb(247,249,252), ORANGE=Color.rgb(238,91,43);
    private final ExecutorService pool=Executors.newFixedThreadPool(4);
    private final ArrayList<Product> items=new ArrayList<>();
    private LinearLayout screen,results; private EditText search; private TextView counter, subtitle;
    private static final int PICK_FILE=141; private Product openProduct; private int photoIndex=0;
    private static class Product {String id,title,sku,url; ArrayList<String> images=new ArrayList<>();}

    @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.WHITE);getWindow().setNavigationBarColor(Color.BLACK);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR);loadCatalog();showHome();}
    private int dp(float n){return (int)(getResources().getDisplayMetrics().density*n+.5f);}
    private GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
    private TextView text(String s,int size,int color,boolean bold){TextView t=new TextView(this);t.setText(s);t.setTextSize(size);t.setTextColor(color);if(bold)t.setTypeface(null,1);return t;}
    private LinearLayout vertical(){LinearLayout v=new LinearLayout(this);v.setOrientation(1);return v;}
    private void marginAdd(LinearLayout parent,View child,int top){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=dp(top);parent.addView(child,lp);}
    private LinearLayout.LayoutParams match(int height){return new LinearLayout.LayoutParams(-1,height<0?height:dp(height));}
    private void showHome(){
        ScrollView sc=new ScrollView(this); sc.setFillViewport(true);sc.setBackgroundColor(BG);setContentView(sc);
        screen=vertical();screen.setPadding(dp(20),dp(26),dp(20),dp(30));sc.addView(screen);
        TextView brand=text("RJ3DART   /   EXPEDIÇÃO",12,ORANGE,true);brand.setLetterSpacing(.09f);screen.addView(brand);
        marginAdd(screen,text("Conferência visual",27,NAVY,true),12);
        subtitle=text("Encontre o produto e confira as fotos antes de embalar.",14,MUTED,false);marginAdd(screen,subtitle,7);
        LinearLayout searchBox=vertical();searchBox.setPadding(dp(12),dp(5),dp(12),dp(5));searchBox.setBackground(bg(Color.WHITE,15));marginAdd(screen,searchBox,24);
        search=new EditText(this);search.setSingleLine(true);search.setTextSize(16);search.setHint("Buscar por nome ou parte do título...");search.setBackgroundColor(Color.TRANSPARENT);search.setCompoundDrawablePadding(dp(8)); searchBox.addView(search,match(52));
        counter=text("",12,MUTED,false);marginAdd(screen,counter,15);
        results=vertical();marginAdd(screen,results,10);
        TextView manage=text("IMPORTAR CATÁLOGO  ·  SINCRONIZAR",12,ORANGE,true);manage.setGravity(Gravity.CENTER);manage.setPadding(dp(8),dp(22),dp(8),dp(22));marginAdd(screen,manage,8);manage.setOnClickListener(v->showMenu());
        search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int a){}public void onTextChanged(CharSequence s,int st,int before,int count){render(s.toString());}public void afterTextChanged(Editable e){}});
        render("");
    }
    private String norm(String v){String n=Normalizer.normalize(v==null?"":v,Normalizer.Form.NFD).replaceAll("\\p{M}","");return n.toLowerCase(Locale.ROOT).replaceAll("[^a-z0-9]+"," ").trim();}
    private boolean matches(Product p,String q){String searchable=norm(p.title+" "+p.sku+" "+p.id),query=norm(q); if(query.isEmpty())return true;for(String part:query.split(" +"))if(!searchable.contains(part))return false;return true;}
    private void render(String query){if(results==null)return;results.removeAllViews();int hits=0;for(Product p:items){if(!matches(p,query))continue;hits++;addCard(p);}counter.setText(hits+" produto(s) encontrado(s)  ·  "+items.size()+" no catálogo");if(hits==0){TextView empty=text("Nenhum produto encontrado.\nExperimente outra palavra ou importe seu catálogo.",15,MUTED,false);empty.setGravity(Gravity.CENTER);empty.setPadding(dp(12),dp(70),dp(12),dp(70));results.addView(empty);}}
    private void addCard(Product p){LinearLayout card=new LinearLayout(this);card.setOrientation(LinearLayout.HORIZONTAL);card.setGravity(Gravity.CENTER_VERTICAL);card.setPadding(dp(10),dp(10),dp(12),dp(10));card.setBackground(bg(Color.WHITE,14));LinearLayout.LayoutParams outer=match(-2);outer.bottomMargin=dp(10);results.addView(card,outer);
        ImageView thumb=new ImageView(this);thumb.setScaleType(ImageView.ScaleType.CENTER_CROP);thumb.setBackground(bg(BG,9));card.addView(thumb,new LinearLayout.LayoutParams(dp(88),dp(88)));if(!p.images.isEmpty())loadImage(thumb,p.images.get(0));
        LinearLayout desc=vertical();desc.setPadding(dp(13),0,0,0);card.addView(desc,new LinearLayout.LayoutParams(0,-2,1));TextView t=text(p.title,14,NAVY,true);t.setMaxLines(3);t.setEllipsize(TextUtils.TruncateAt.END);desc.addView(t);TextView info=text(p.images.size()+" foto(s)  •  Toque para conferir",12,ORANGE,false);marginAdd(desc,info,7);if(!p.sku.isEmpty())marginAdd(desc,text("SKU: "+p.sku,11,MUTED,false),4);card.setOnClickListener(v->{((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);openProduct=p;photoIndex=0;showPhoto();});
    }
    private void showPhoto(){if(openProduct==null)return;ScrollView sc=new ScrollView(this);sc.setBackgroundColor(Color.WHITE);setContentView(sc);LinearLayout root=vertical();root.setPadding(dp(18),dp(20),dp(18),dp(28));sc.addView(root);TextView back=text("‹   Voltar para busca",15,ORANGE,true);root.addView(back);back.setOnClickListener(v->{openProduct=null;showHome();});marginAdd(root,text(openProduct.title,20,NAVY,true),24);
        ImageView large=new ImageView(this);large.setScaleType(ImageView.ScaleType.FIT_CENTER);large.setBackground(bg(BG,14));LinearLayout.LayoutParams pic=match(370);pic.topMargin=dp(22);root.addView(large,pic);if(!openProduct.images.isEmpty())loadImage(large,openProduct.images.get(photoIndex));else large.setContentDescription("Produto sem fotos no catálogo");
        TextView pager=text(openProduct.images.isEmpty()?"Nenhuma foto cadastrada":(photoIndex+1)+" / "+openProduct.images.size(),14,MUTED,true);pager.setGravity(Gravity.CENTER);marginAdd(root,pager,15);
        LinearLayout buttons=new LinearLayout(this);buttons.setGravity(Gravity.CENTER);marginAdd(root,buttons,12);Button prev=new Button(this);prev.setText("‹ ANTERIOR");buttons.addView(prev,new LinearLayout.LayoutParams(0,dp(54),1));Button next=new Button(this);next.setText("PRÓXIMA ›");buttons.addView(next,new LinearLayout.LayoutParams(0,dp(54),1));prev.setEnabled(photoIndex>0);next.setEnabled(photoIndex<openProduct.images.size()-1);prev.setOnClickListener(v->{photoIndex--;showPhoto();});next.setOnClickListener(v->{photoIndex++;showPhoto();});
        TextView ready=text("✓   CONFERIDO — VOLTAR À BUSCA",14,Color.WHITE,true);ready.setGravity(Gravity.CENTER);ready.setBackground(bg(ORANGE,12));ready.setPadding(dp(10),dp(20),dp(10),dp(20));marginAdd(root,ready,22);ready.setOnClickListener(v->{openProduct=null;showHome();});
        if(openProduct.url!=null && openProduct.url.startsWith("https://")){TextView link=text("Abrir anúncio na Shopee",13,ORANGE,false);link.setGravity(Gravity.CENTER);marginAdd(root,link,18);link.setOnClickListener(v->startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(openProduct.url))));}
    }
    @Override public void onBackPressed(){if(openProduct!=null){openProduct=null;showHome();}else super.onBackPressed();}
    private void showMenu(){String[] actions={"Importar JSON ou CSV do celular", "Atualizar catálogo por URL HTTPS", "Restaurar catálogo de demonstração"};new AlertDialog.Builder(this).setTitle("Gerenciar catálogo").setItems(actions,(d,which)->{if(which==0){Intent intent=new Intent(Intent.ACTION_OPEN_DOCUMENT);intent.setType("*/*");intent.addCategory(Intent.CATEGORY_OPENABLE);intent.putExtra(Intent.EXTRA_MIME_TYPES,new String[]{"application/json","text/csv","text/comma-separated-values","text/plain","application/octet-stream"});startActivityForResult(intent,PICK_FILE);}else if(which==1)askUrl();else new AlertDialog.Builder(this).setTitle("Restaurar demonstração?").setMessage("Substituirá o catálogo atual.").setPositiveButton("Restaurar",(x,y)->{getPreferences(0).edit().remove("catalog").apply();loadCatalog();showHome();}).setNegativeButton("Cancelar",null).show();}).show();}
    private void askUrl(){EditText field=new EditText(this);field.setSingleLine(true);field.setInputType(17);field.setHint("https://seu-servidor/catalogo.json");String saved=getPreferences(0).getString("url","");field.setText(saved);new AlertDialog.Builder(this).setTitle("Catálogo remoto").setMessage("Informe uma URL HTTPS que retorne o JSON do catálogo. O aplicativo só acessará esse endereço ao solicitar a atualização.").setView(field).setPositiveButton("Atualizar",(dialog,which)->{String url=field.getText().toString().trim();if(!url.startsWith("https://")){toast("Use um endereço HTTPS.");return;}getPreferences(0).edit().putString("url",url).apply();pool.execute(()->{try{URL u=new URL(url);HttpURLConnection c=(HttpURLConnection)u.openConnection();c.setConnectTimeout(10000);c.setReadTimeout(15000);c.setInstanceFollowRedirects(false);if(c.getResponseCode()!=200)throw new IOException("HTTP "+c.getResponseCode());String data=readLimited(c.getInputStream(),3_000_000);applyImported(data,false);}catch(Exception e){runOnUiThread(()->toast("Não foi possível atualizar: "+e.getMessage()));}});}).setNegativeButton("Cancelar",null).show();}
    @Override protected void onActivityResult(int req,int result,Intent data){super.onActivityResult(req,result,data);if(req==PICK_FILE && result==RESULT_OK && data!=null){try(InputStream in=getContentResolver().openInputStream(data.getData())){String value=readLimited(in,3_000_000);String path=data.getData().toString().toLowerCase(Locale.ROOT);applyImported(value,path.endsWith(".csv")||(!value.trim().startsWith("{")&&!value.trim().startsWith("[")));}catch(Exception e){toast("Erro na importação: "+e.getMessage());}}}
    private void applyImported(String input,boolean csv){try{ArrayList<Product> parsed=csv?parseCsv(input):parseJson(input);if(parsed.isEmpty())throw new Exception("nenhum produto válido");JSONArray arr=new JSONArray();for(Product p:parsed){JSONObject o=new JSONObject();o.put("id",p.id);o.put("title",p.title);o.put("sku",p.sku);o.put("url",p.url);o.put("images",new JSONArray(p.images));arr.put(o);}getPreferences(0).edit().putString("catalog",new JSONObject().put("products",arr).toString()).apply();runOnUiThread(()->{loadCatalog();openProduct=null;showHome();toast(parsed.size()+" produtos importados!");});}catch(Exception e){runOnUiThread(()->toast("Catálogo inválido: "+e.getMessage()));}}
    private void loadCatalog(){items.clear();try{String raw=getPreferences(0).getString("catalog",null);if(raw==null){try(InputStream in=getAssets().open("catalogo_exemplo.json")){raw=readLimited(in,3_000_000);}}items.addAll(parseJson(raw));}catch(Exception e){toast("Não foi possível ler o catálogo.");}}
    private ArrayList<Product> parseJson(String raw)throws Exception{JSONArray array=raw.trim().startsWith("[")?new JSONArray(raw):new JSONObject(raw).getJSONArray("products");ArrayList<Product> list=new ArrayList<>();Set<String> ids=new HashSet<>();for(int i=0;i<array.length();i++){JSONObject obj=array.getJSONObject(i);Product p=new Product();p.title=obj.optString("title",obj.optString("name","")).trim();p.id=obj.optString("id",String.valueOf(i));p.sku=obj.optString("sku","");p.url=obj.optString("url","");JSONArray imgs=obj.optJSONArray("images");if(imgs!=null){for(int j=0;j<imgs.length();j++){String img=imgs.optString(j);if(img.startsWith("https://"))p.images.add(img);}}else{String img=obj.optString("image","");if(img.startsWith("https://"))p.images.add(img);}if(!p.title.isEmpty()&&ids.add(p.id))list.add(p);}return list;}
    private ArrayList<Product> parseCsv(String raw)throws Exception{String normalized=raw.replace("\r\n","\n").replace('\r','\n');String first=normalized.split("\n",2)[0];char sep=first.contains(";")?';':',';ArrayList<ArrayList<String>> rows=csvRows(normalized,sep);if(rows.size()<2)throw new Exception("CSV vazio");ArrayList<String> heads=rows.get(0);int title=-1,id=-1,sku=-1,photo=-1,url=-1;for(int i=0;i<heads.size();i++){String h=norm(heads.get(i));if(h.equals("title")||h.equals("titulo")||h.equals("nome do produto")||h.equals("nome do anuncio")||h.equals("product name"))title=i;else if(h.equals("id")||h.equals("item id")||h.equals("id do produto"))id=i;else if(h.equals("sku")||h.equals("sku principal"))sku=i;else if(h.equals("images")||h.equals("image")||h.equals("fotos")||h.equals("imagens")||h.equals("url da imagem"))photo=i;else if(h.equals("url")||h.equals("link"))url=i;}if(title<0)throw new Exception("coluna de título não encontrada");ArrayList<Product> out=new ArrayList<>();HashMap<String,Product> byKey=new HashMap<>();for(int i=1;i<rows.size();i++){ArrayList<String> r=rows.get(i);String name=val(r,title).trim();if(name.isEmpty())continue;String identifier=val(r,id).trim();String key=!identifier.isEmpty()?identifier:norm(name);Product p=byKey.get(key);if(p==null){p=new Product();p.title=name;p.id=identifier.isEmpty()?"csv-"+i:identifier;p.sku=val(r,sku);p.url=val(r,url);byKey.put(key,p);out.add(p);}String photos=val(r,photo);for(String image:photos.split("[|\\n]")){image=image.trim();if(image.startsWith("https://")&&!p.images.contains(image))p.images.add(image);}}return out;}
    private String val(ArrayList<String> row,int i){return i>=0&&i<row.size()?row.get(i):"";}
    private ArrayList<ArrayList<String>> csvRows(String raw,char sep){ArrayList<ArrayList<String>> rows=new ArrayList<>();ArrayList<String> row=new ArrayList<>();StringBuilder field=new StringBuilder();boolean quote=false;for(int i=0;i<raw.length();i++){char c=raw.charAt(i);if(c=='"'){if(quote&&i+1<raw.length()&&raw.charAt(i+1)=='"'){field.append('"');i++;}else quote=!quote;}else if(c==sep&&!quote){row.add(field.toString());field.setLength(0);}else if(c=='\n'&&!quote){row.add(field.toString());field.setLength(0);rows.add(row);row=new ArrayList<>();}else field.append(c);}if(field.length()>0||!row.isEmpty()){row.add(field.toString());rows.add(row);}return rows;}
    private String readLimited(InputStream in,int limit)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] buf=new byte[8192];int count=0,n;while((n=in.read(buf))!=-1){count+=n;if(count>limit)throw new IOException("arquivo maior que 3 MB");out.write(buf,0,n);}return out.toString("UTF-8");}
    private void toast(String s){Toast.makeText(this,s,Toast.LENGTH_LONG).show();}
    private File cachedFile(String url){try{MessageDigest digest=MessageDigest.getInstance("SHA-256");byte[] hash=digest.digest(url.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:hash)s.append(String.format(Locale.ROOT,"%02x",b));return new File(getCacheDir(),s+".jpg");}catch(Exception e){return new File(getCacheDir(),String.valueOf(url.hashCode())+".jpg");}}
    private void loadImage(ImageView view,String url){view.setTag(url);view.setImageDrawable(null);pool.execute(()->{try{File cache=cachedFile(url);Bitmap bm;if(cache.exists())bm=BitmapFactory.decodeFile(cache.getAbsolutePath());else{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);c.setInstanceFollowRedirects(true);try(InputStream in=c.getInputStream();FileOutputStream out=new FileOutputStream(cache)){byte[] buf=new byte[8192];int n,total=0;while((n=in.read(buf))!=-1){total+=n;if(total>8_000_000)throw new IOException("imagem muito grande");out.write(buf,0,n);}}finally{c.disconnect();}bm=BitmapFactory.decodeFile(cache.getAbsolutePath());}if(bm!=null)runOnUiThread(()->{if(url.equals(view.getTag()))view.setImageBitmap(bm);});}catch(Exception ignored){} });}
}
